{\it Let $\,\varphi \colon A\to \bar{A}\,$ be a morphism of functor of rings between oriented cohomology theories, whose associated series $\mathrm{S} \in \bar{A}(*)[[t]] $ is invertible.  For any projective morphism $\,f \colon Y \to X\,$ between smooth, quasi-projective $k$-varieties, the following diagram commutes
\begin{equation*}
\vcenter{\xymatrix{
A(Y)  \ar[rrr]^-{f_*} \ar[d]_{\varphi} & & & A(X) \ar[d]^{\varphi} \\
\bar{A}(Y) \ar[rrr]^-{f_* ( \mathrm{S}_{\times}^{-1} (T_f) \cdot  \ \underline{\phantom{a}}\  )  } & & & \bar{A} (X)}} 
\end{equation*} where $\mathrm{S}_\times^{-1} \colon K \to \bar{A}$ denotes the multiplicative extension of the series $\mathrm{S}^{-1}$.}

{\it Let $\,\varphi \colon A \to \bar{A}\,$ be a morphism of functor of rings between oriented cohomology theories, with associated series $\, \mathrm{S} \in \bar{A}(*)[[t]]\,$.  For any closed inmersion $\, i \colon Z \hookrightarrow X\,$, the following square commutes:
\begin{equation*}
\vcenter{\xymatrix{
A(Z)  \ar[rrr]^-{i_*} \ar[d]_{\varphi} & & & A(X) \ar[d]^{\varphi} \\
\bar{A} (Z) \ar[rrr]^-{i_* (\mathrm{S}_{\times} (N_i) \cdot  \ \underline{\phantom{a}}\  ) } & & & \bar{A}(X)}}
\end{equation*}
where $\, N_i := i^* T_{X} - T_Z = - T_i\,$ denotes the normal bundle of $i$. }

\label{FGL}
A {\it commutative formal group law} over a ring $\,R\,$ is a power series $\,f(u,v) \in R[[u,v]]\,$ that satisfies the axioms for a commutative group operation with $0$ as the neutral element; namely,
\begin{itemize}
\item[a)] $f(u,v) = f(v,u) \in R[[u,v]]$. 
\item[b)] $f(u,0) = u \in R[[u]] $.
\item[c)] $f(u, f(v,w)) = f(f(u,v), w) \in R[[u,v,w]]$. 
\item[d)] There exist a series $\, opp(u) \in R[[u]]\,$ such that $\, opp(0) = 0\,$ and $\,f(u, opp(u) ) = 0 \in R[[u]]$. 
\end{itemize}
The {\it additive group law} is $f(u , v)= u + v\ ,$ and the {\it multiplicative}                                                           
{\it group law} is $f(u ,v)= u+v-uv$.

\label{RelationXeY} 


\begin{enumerate} 
\item
Graded cohomology theories follow the additive group law (\cite[Lemma 3.1]{ExpositionesI}). These examples include all Weil cohomologies or the Chow ring.

\item Grothendieck's $K$-theory follows the multiplicative group law,  whereas algebraic cobordism follows the universal group law (in particular,  $\, \Omega^{\bullet} (*) \,$ is the Lazard ring,  see \cite{LevineMorel}).

\item
The equality $\xi_d \otimes \xi^*_d = \mathcal{O}_X$ implies a relation between the Chern classes $x_d = c_1^A (\xi_d)$ and $y_d = c_1^A(\xi^*_d)$: if $A$ follows the additive law, then $x_d=- y_d$, whereas, if $A$ follows the multiplicative law, then $x_d =-y_d/(1-y_d)$.                                         

\end{enumerate}

\label{UnicidadMorfismoGrupos}
Let $A$ be an oriented cohomology. 
Morphisms of functor of monoids $\,\phi \colon K^+ \to (A , \cdot )$, as well as morphisms of functor of groups $\,\phi \colon K \to A\,$, are determined by their values on the tautological line bundles $\,\{\xi_d\}_{d\in \mathbb{N}}$.

\label{MorfismosDeGrupos}
Any morphism of functor of monoids $\, \phi \colon K^+ \to (A,\cdot) \,$ is the multiplicative extension, $\phi = F_\times$, of a unique series $\,F \in A(*)[[t]]$.


Any morphism of functor of groups $\, \phi \colon K \to A\,$ is the additive extension, $\phi = F_+$, of a unique series $\,F \in A(*)[[t]]$.

\label{EjemSm}
The additive extensions of the monomials $\,t^m\,$ are morphisms of groups:
$$ s_m \colon K \to A \quad , \quad s_m (E) = \alpha_1^m + \ldots + \alpha_r^m \ , $$ which, due to the Newton's formulae, can be written in terms of the Chern classes:
\begin{align*}
s_0(E) &= \operatorname{rank} ( E) \\
s_1 (E) &= c_1^A (E) \\
s_2 (E) &= c_1^A (E)^2 - 2 c_2^A(E) \\ \ldots

\end{align*}

\label{MorfismosAnillos}
Any morphism of functor of rings $\,\varphi \colon K \to A\,$ is the additive extension, $\varphi = F_+$, of a unique series $\, F \in A(*) [[t]]\,$ satisfying
\begin{equation}\label{MorfismoFGL}
F( f^A (x,y) ) = F(x) \cdot F(y) \ .
\end{equation}

\label{SerieAsociada} Let $\,\phi \colon A \to \bar{A}\,$ be a morphisms of functor of groups. There exists a unique series $\, \mathrm{S} \in \bar{A}(*)[[t]]\,$, called the {\it series associated to} $\,\phi\,$, such that 
\begin{equation*}
 \phi (x_d ) \, = \, \mathrm{S} (\bar{x}_d)\, \bar{x}_d  \ ,                                                             
\end{equation*}
for all $\, d \in \mathbb{N} \cup \{0\}$.

\label{Main}
Let $\,\varphi \colon A \to \bar{A}\,$ be a morphism of functor of rings, with associated series $\, \mathrm{S} \in \bar{A}(*)[[t]]\,$. For any closed inmersion $\, i \colon Z \hookrightarrow X\,$, the following square commutes:
\begin{equation*}\label{CuadradoEntero}
\vcenter{\xymatrix{
A(Z)  \ar[rrr]^-{i_*} \ar[d]_{  \varphi} & & & A(X) \ar[d]^{\varphi} \\
\bar{A} (Z) \ar[rrr]^-{\bar i_* ( \mathrm{S}_{\times} (N_i) \cdot \ \underline{\phantom{a}}\  ) } &  &  & \bar{A}(X),} }
\end{equation*}
where $\, N_i := i^* T_{X} - T_Z \,$ denotes the normal bundle of $i$. 

In other words, for any element $a \in A(Z)$,
\begin{equation}\label{EcuacionEntera}
\varphi \, i_*(a)  \, =\,  \bar i_*\left( \mathrm{S}_{\times} (N_i) \cdot \varphi(a)\right) \ .
\end{equation}

\label{CoroRRAsindeno}
For  any closed inmersion $\, i \colon Z \hookrightarrow X\,$ and any $\,j \in \mathbb{Z}$, the square below commutes:
\begin{equation*}
\vcenter{\xymatrix{
K(Z)  \ar[rrr]^-{i_*} \ar[d]_{ \psi^j} & & & K(X) \ar[d]^{\psi^j} \\
K(Z) \ar[rrr]^-{i_* (\theta^j (N_i^*) \cdot \ \underline{\phantom{a}}\  ) } & &  & K(X)  \ , }}
\end{equation*} where $N^*_i$ is the conormal bundle and $\theta^j \colon K^+ \to (K, \cdot ) $ is the morphism of functor of monoids defined on line bundles as
$$ 
\theta^j (L) := 1 + L + \ldots + L^{j-1} = \frac{1-L^j}{1-L} \ . 
$$

\label{FORMULA_NUEVA}
Let $A$ be a cohomology theory following the additive law, and such that  $A(*)$ is a ring where $1, 2, \ldots , p-1$ are units and that contains a nilpotent element $\varepsilon$ of order $p$ (\emph{cf. } Example \ref{EjMorfismos}.3).  For  any closed inmersion $\, i \colon Z \hookrightarrow X\,$, the square below commutes:
\begin{equation*}
\vcenter{\xymatrix{
K(Z)  \ar[rrr]^-{i_*} \ar[d]_{\mathrm {ch}_{\varepsilon}} & & & K(X) \ar[d]^{\mathrm {ch}_{\varepsilon}} \\
A(Z) \ar[rrr]^-{i_* ( \mathsf{T}_{\varepsilon} (N_i) \cdot \ \underline{\phantom{a}}\  ) } & & & A(X)  \ , }}
\end{equation*} where $\mathsf{T}_{\varepsilon} \colon K^+ \to A$ is the multiplicative extension of the (non-invertible) polyomial $\varepsilon - \frac{\varepsilon^2}{2}\,t +  \ldots + \frac{\varepsilon^{p-1}}{(p-1)!}\, (-t)^{p-2} $.

\label{RRA} 
For any $j \in \mathbb{Z}$, the Adams operation $\psi^j$ is a morphism of cohomologies
$$ \psi^j \colon K \longrightarrow \left( K \otimes \mathbb{Z}[j^{-1}] \, , \,  f_{*}^{\mathsf{B}^j} \right)\  . $$                                                                                              

Equivalently, for any projective morphism $\,f\colon Y\to X\,$ between smooth quasi-projective $k$-varieties, the following diagram commutes:
\begin{equation*}\label{RRAClasico}
\vcenter{\xymatrix{
K(Y)  \ar[rrr]^-{f_*} \ar[d]_{\psi^j} & & & K(X) \ar[d]^{\psi^j} \\
K(Y)\otimes \mathbb{Z}[j^{-1}]  \ar[rrr]^-{f_* \left( \theta^j (\Omega_f)^{-1} \cdot \ \underline{\phantom{a}}\  \right)  } & & &K(X) \otimes \mathbb{Z}[j^{-1}]  \ , }}
\end{equation*}
where $\Omega_f = T_f^* \in K(Y) $ is the relative cotangent bundle.

\label{RRG} 
Let $A$ be an oriented cohomology following the additive group law and such that $A(*)$ is a $\mathbb{Q}$-algebra.  The Chern character is a morphism of  cohomologies
$$ \mathrm {ch} \colon K \longrightarrow \left( A  \, , \,  f_{*}^{\mathsf{T}} \right) \ , $$ where $\mathsf{T} = \frac{1-e^{-t}}{t}$ is its associated series (\emph{cf. } Example \ref{EjemSeries}.3).

Equivalently, for any projective morphism $\,f\colon Y\to X\,$ between smooth quasi-projective $k$-varieties, the diagram below commutes:
$$
\xymatrix{
K(Y)  \ar[rrr]^-{f_*} \ar[d]_{\mathrm {ch}} & & &  K(X) \ar[d]^{\mathrm {ch}} \\
A(Y) \ar[rrr]^-{f_* \left( \operatorname{Td} (T_f) \cdot \ \underline{\phantom{a}}\  \right)  } & & &  A(X)  \ , }
$$
where $\,\operatorname{Td} \colon K \to A \,$ is the multiplicative extension of the Todd series $\frac{t}{1-e^{-t}}$.

\label{TeoremaCuboMagico}
The following diagram is a commutative square of isomorphisms of cohomologies:
\begin{equation}\label{CuadradoCohomologias}
\vcenter{\xymatrix{K_\mathbb{Q}\ar[d]_-{\mathrm {ch} }\ar[rr]^-{\psi^j} & & \left( K_\mathbb{Q} , f^{\mathsf{B}^j}_{* } \right) \ar[d]^-{\mathrm {ch}}\\

\left( CH_\mathbb{Q} , f^{\mathsf{T}}_{*} \right) \ar[rr]^-{\Phi^j}& & \left( CH_\mathbb{Q}, f^{\mathrm{S}^j}_{* } \right)}}
\end{equation} 

That is to say, the arrows above are isomorphisms of functor of rings such that, for any projective morphism $\,f\colon Y\to X\,$ between smooth, quasi-projective $k$-varieties, the cube below commutes:  
\begin{equation*}\label{CuboMagico}
\vcenter{\xymatrix@C-28
pt{ K(Y)_{\mathbb{Q}} \ar[dr]^{\Psi^j} \ar[dd]_{ \mathrm{ch} } \ar[rrr]^{ f_*} & & \qquad \phantom{A} \qquad  & K(X)_{\mathbb{Q}} \ar[dr]^{\Psi^j} \ar'[d][dd]^(.45){\mathrm{ch}}   &
\\
&  K(Y)_{\mathbb{Q}} \ar[dd]_(.30){\mathrm{ch}}\ar[rrr]^(.40){f_* \left( \theta^j (\Omega_f)^{-1} \cdot \ \underline{\phantom{a}}\  \right) } & & & K(X)_{\mathbb{Q}}  \ar[dd]^{\mathrm{ch}}
\\
 CH(Y)_\mathbb{Q} \ar[dr]_{\Phi^j} \ar'[r][rrr]^(.40){f_* (\mathrm{Td} (T_f) \cdot \ \underline{\phantom{a}}\  ) }& & & CH(X)_\mathbb{Q} \ar[dr]^{\Phi^j} &
\\
& CH(Y)_\mathbb{Q} \ar[rrr]^{f_* (\mathrm{S}^j (-T_f) \cdot \ \underline{\phantom{a}}\  ) } & & & CH(X)_\mathbb{Q} 
}} 
\end{equation*}
